// Build the header row + string matrix. The workflow now OWNS the schema:
// it writes exactly the columns it can fill, so headers come from the query.
const rows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => Object.keys(r).length > 0);

const toText = (v) => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
};

if (rows.length === 0) {
  return [{ json: { row_count: 0, column_count: 0, columns: [], records: [], snapshot_date: '' } }];
}

const columns = [];
for (const r of rows) for (const k of Object.keys(r)) if (!columns.includes(k)) columns.push(k);

const seen = new Set();
const records = [];
const teams = new Set();
const managers = new Set();
for (const r of rows) {
  const id = toText(r['Employee ID']);
  if (id !== '' && seen.has(id)) continue;
  seen.add(id);
  records.push(columns.map((c) => toText(r[c])));
  if (toText(r['Team']) !== '') teams.add(toText(r['Team']));
  if (toText(r["Manager's Name"]) !== '') managers.add(toText(r["Manager's Name"]));
}

return [{ json: {
  row_count: records.length,
  column_count: columns.length,
  columns,
  records,
  teams_present: [...teams].sort(),
  manager_count: managers.size,
  snapshot_date: toText(rows[0]['Snapshot Date']),
} }];

// Turn the diagnostic rows into an actionable error message.
const rows = $input.all().map((i) => i.json || {}).filter((r) => Object.keys(r).length > 0);
const L = [];
L.push('FRONTLINE ROSTER REFRESH ABORTED - the query returned zero rows.');
L.push('The Google Sheet was NOT cleared. Its previous contents are intact.');
L.push('');

if (rows.length === 0) {
  L.push('DIAGNOSIS: no rows at all in this table for the last 400 days.');
  L.push('Either it is no longer populated, or this BigQuery credential cannot');
  L.push('read it. Verify with:');
  L.push('  SELECT COUNT(*) FROM `wf-gcp-us-ae-cs-prod.cs_reporting.tbl_customer_service_employee_performance_manager`');
} else {
  const day = rows.filter((r) => String(r.datetype_value).toLowerCase() === 'day');
  const fresh = day.filter((r) => Number(r.days_stale) <= 30);
  L.push('Table contents over the last 400 days (datetype | team | rows | employees | newest | days stale | active):');
  L.push('');
  for (const r of rows.slice(0, 30)) {
    L.push(`  ${r.datetype_value} | ${r.team_value} | ${r.row_count} | ${r.distinct_employees} | ${r.max_date} | ${r.days_stale}d | ${r.active_rows}`);
  }
  L.push('');
  if (day.length === 0) {
    L.push('DIAGNOSIS: no rows with datetype="Day". Change that filter to a value above.');
  } else if (fresh.length === 0) {
    L.push(`DIAGNOSIS: the newest "Day" snapshot is ${day[0].days_stale} days old, outside`);
    L.push('the 30-day window. The window is deliberately narrow so stale data is never');
    L.push('published as current. Fix the upstream pipeline rather than widening it.');
  } else {
    const teams = [...new Set(fresh.map((r) => r.team_value))].sort();
    L.push('DIAGNOSIS: fresh "Day" rows exist, so the FRONTLINE SCOPE filter matched nothing.');
    L.push('');
    L.push('The real team values available are:');
    for (const tv of teams) L.push(`  ${tv}`);
    L.push('');
    L.push('NEXT STEP: open the BigQuery node and replace the scope line');
    L.push("  AND t.team IN ('Frontline')");
    L.push('with the values above that make up your frontline, e.g.');
    L.push(`  AND t.team IN ('${teams.slice(0, 2).join("', '")}')`);
  }
}
return [{ json: { diagnosis: L.join('\n') } }];

// One values:batchUpdate body per chunk. Header row is row 1 of the payload.
const TAB_NAME = 'Sheet1';
const CHUNK_ROWS = 5000;

const source = $('Code - Normalize Roster').first().json;
const allRows = [source.columns || [], ...(source.records || [])];
const chunks = [];

for (let offset = 0; offset < allRows.length; offset += CHUNK_ROWS) {
  const slice = allRows.slice(offset, offset + CHUNK_ROWS);
  const startRow = offset + 1;
  chunks.push({
    chunk_index: chunks.length + 1,
    chunk_rows: slice.length,
    start_row: startRow,
    request_body: {
      valueInputOption: 'RAW',
      data: [{ range: `${TAB_NAME}!A${startRow}`, majorDimension: 'ROWS', values: slice }],
    },
  });
}
return chunks.map((c) => ({ json: { ...c, chunk_total: chunks.length } }));

const source = $('Code - Normalize Roster').first().json;
const chunks = $('Code - Build Sheets Write Chunks').all();
return [{ json: {
  status: 'SUCCESS',
  spreadsheet_id: '1w-PBwKVwLoqQ7tF22baZFKAvb-Gn6f29Brwv1OdIPf4',
  tab_name: 'Sheet1',
  scope: "Frontline - active employees where team IN ('Frontline')",
  employee_row_count: source.row_count,
  distinct_manager_count: source.manager_count,
  teams_present: source.teams_present,
  column_count: source.column_count,
  columns_written: source.columns,
  snapshot_date: source.snapshot_date,
  sheets_write_requests_used: chunks.length + 1,
  schedule: 'Mondays 04:00 America/Phoenix (Arizona, no DST) = 11:00 UTC',
} }];
